{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Investment — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff9f6;--muted:#6b6b6b;--accent:#6a8a6a;--card:#ffffff;--glass:rgba(255,255,255,0.6);--shadow:0 6px 18px rgba(34,34,34,0.08);--accent2:#97bfb2}
    html,body{height:100%;margin:0;font-family:Inter,ui-sans-serif,system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:#213;line-height:1.4}
    header{background:linear-gradient(180deg,rgba(106,138,106,0.08),transparent);padding:28px 20px;display:flex;align-items:center;justify-content:space-between}
    .brand{display:flex;align-items:center;gap:14px}
    .logo{width:56px;height:56px;border-radius:12px;background:linear-gradient(135deg,var(--accent),var(--accent2));display:flex;align-items:center;justify-content:center;color:white;font-weight:700}
    nav a{margin:0 10px;color:#274; text-decoration:none;font-weight:600}
    .container{max-width:1100px;margin:28px auto;padding:0 20px}
    .hero{display:grid;grid-template-columns:1fr 360px;gap:22px;align-items:start}
    .hero-card{background:var(--card);padding:22px;border-radius:14px;box-shadow:var(--shadow)}
    h1{margin:0 0 8px;font-size:28px}
    p.lead{margin:0;color:var(--muted)}
    .tiers{display:flex;gap:18px;margin-top:20px;flex-wrap:wrap}
    .tier{flex:1 1 260px;background:linear-gradient(180deg,#fff,#fbfbfb);border:1px solid rgba(33,33,33,0.04);padding:18px;border-radius:12px}
    .price{font-size:22px;font-weight:700;color:#133}
    .muted{color:var(--muted)}
    .btn{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:10px;text-decoration:none;font-weight:700}
    .note{font-size:13px;color:var(--muted);margin-top:10px}
    footer{margin-top:40px;padding:28px 20px;background:url('assets/img/pattern.svg') repeat;}
    .grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    /* Habit builder small */
    .builder{background:linear-gradient(180deg,#fff,#fcf9f6);padding:14px;border-radius:10px;border:1px solid rgba(0,0,0,0.05)}
    label{display:block;margin:8px 0 6px;font-weight:600}
    input[type="text"],select,input[type="number"]{width:100%;padding:8px;border-radius:8px;border:1px solid #e6e6e6}
    .checklist{margin-top:12px}
    .checklist li{background:#fff;padding:8px;border-radius:8px;margin-bottom:6px;list-style:none;display:flex;justify-content:space-between;align-items:center}
    .small{font-size:13px;color:var(--muted)}
    .accent-link{color:var(--accent);font-weight:700}
    @media(max-width:900px){.hero{grid-template-columns:1fr}
      .grid{grid-template-columns:1fr}
    }
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">WC</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div class="small">{{TAGLINE}}</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Studio</a>
      <a href="about.html">Meet</a>
      <a href="services.html">Offerings</a>
      <a href="programs.html">Programs</a>
      <a href="pricing.html">Rates</a>
      <a href="testimonials.html">Praise</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main class="container">
    <section class="hero">
      <div class="hero-card">
        <h1>Investment with intention — cohorts and supported paths</h1>
        <p class="lead">Join a small, guided cohort designed to nudge durable habits into your week. We blend prompts, measurable practices, and live check-ins so you leave each cycle with a practical rhythm.</p>
        <div class="tiers">
          <div class="tier">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div style="font-weight:800">Spark Cohort</div>
                <div class="muted">4-week small group</div>
              </div>
              <div class="price">$349</div>
            </div>
            <p class="small">Weekly group session + personal check-ins. A compact, social way to lock in new practices.</p>
            <div style="margin-top:12px">
              <a class="btn" href="book.html">Claim your spot — Spark</a>
            </div>
          </div>

          <div class="tier">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div style="font-weight:800">Seasonal Cohort</div>
                <div class="muted">12-week supported cycle</div>
              </div>
              <div class="price">$980</div>
            </div>
            <p class="small">A paced three-month arc with workshops, templates, and two private sessions included.</p>
            <div style="margin-top:12px">
              <a class="btn" href="book.html">Reserve a seat — Seasonal</a>
            </div>
          </div>

          <div class="tier">
            <div style="display:flex;justify-content:space-between;align-items:center">
              <div>
                <div style="font-weight:800">Self-Paced Spark</div>
                <div class="muted">365 days access</div>
              </div>
              <div class="price">$149</div>
            </div>
            <p class="small">Work through the same practices on your own schedule with templates and checklists.</p>
            <div style="margin-top:12px">
              <a class="btn" href="#builder">Start a 7-day preview</a>
            </div>
          </div>
        </div>

        <p class="note">Cohorts run with capped seats. Payment plans available — ask at <a class="accent-link" href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
      </div>

      <aside class="hero-card">
        <h3 style="margin-top:0">Compare the runs</h3>
        <div class="grid" style="margin-top:12px">
          <div style="background:var(--glass);padding:12px;border-radius:10px">
            <strong>Group energy</strong>
            <div class="muted small">Peer accountability & structured deadlines</div>
          </div>
          <div style="background:var(--glass);padding:12px;border-radius:10px">
            <strong>Private focus</strong>
            <div class="muted small">Targets and one-on-one calibration</div>
          </div>
        </div>

        <div style="margin-top:14px">
          <div class="muted small">Quick tool: craft a tiny habit loop and print a 7-day checklist.</div>
          <div id="builder" class="builder" style="margin-top:10px">
            <label for="habitName">7-Day challenge name</label>
            <input id="habitName" type="text" placeholder="e.g., Morning 10-minute reset" />
            <label for="habitAction">Core action</label>
            <input id="habitAction" type="text" placeholder="e.g., 10 minutes of stretching + breath" />
            <label for="habitIntensity">Intensity (notes)</label>
            <input id="habitIntensity" type="text" placeholder="e.g., gentle, energizing, restorative" />
            <div style="display:flex;gap:8px;margin-top:10px">
              <button id="buildBtn" class="btn">Make 7-day plan</button>
              <button id="printChecklist" style="padding:10px;border-radius:8px;border:1px solid #e6e6e6;background:#fff">Print</button>
            </div>
            <ol id="checklist" class="checklist"></ol>
          </div>
        </div>
      </aside>
    </section>

    <section style="margin-top:26px">
      <div class="hero-card">
        <h3 style="margin:0 0 10px">Flexible support add-ons</h3>
        <div style="display:flex;gap:14px;flex-wrap:wrap">
          <div style="background:#fff;padding:12px;border-radius:10px;border:1px solid #efefef;flex:1;min-width:220px">
            <strong>One-off Clarity Session</strong>
            <div class="muted small">60 minutes to map a concise focus plan</div>
            <div style="margin-top:8px"><a class="btn" href="book.html">Book clarity</a></div>
          </div>

          <div style="background:#fff;padding:12px;border-radius:10px;border:1px solid #efefef;flex:1;min-width:220px">
            <strong>Check-in bundle (3)</strong>
            <div class="muted small">Three 30-minute check-ins across 8 weeks</div>
            <div style="margin-top:8px"><a class="btn" href="book.html">Add check-ins</a></div>
          </div>
        </div>
      </div>
    </section>

  </main>

  <footer>
    <div class="container">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap">
        <div>
          <strong>{{BUSINESS_NAME}}</strong>
          <div class="small">Serving {{CITY}}, {{STATE}} — <a href="tel:{{PHONE}}">{{PHONE}}</a></div>
        </div>
        <div class="small">Questions? <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></div>
      </div>
    </div>
  </footer>

  <script>
    // Habit builder: creates a 7-day printable checklist
    (function(){
      const buildBtn = document.getElementById('buildBtn');
      const printBtn = document.getElementById('printChecklist');
      const habitName = document.getElementById('habitName');
      const habitAction = document.getElementById('habitAction');
      const habitIntensity = document.getElementById('habitIntensity');
      const checklist = document.getElementById('checklist');

      function renderList(name, action, intensity){
        checklist.innerHTML = '';
        for(let d=1; d<=7; d++){
          const li = document.createElement('li');
          li.textContent = 'Day ' + d + ': ' + (action || 'Do the habit') + ' — ' + (intensity || 'as feels right');
          checklist.appendChild(li);
        }
      }

      buildBtn.addEventListener('click', function(){
        renderList(habitName.value, habitAction.value, habitIntensity.value);
      });

      printBtn.addEventListener('click', function(){
        const name = habitName.value || '7-day challenge';
        const action = habitAction.value || 'habit action';
        const intensity = habitIntensity.value || '';
        let win = window.open('', '_blank');
        win.document.write('<html><head><title>' + name + '</title></head><body>');
        win.document.write('<h2>' + name + '</h2>');
        win.document.write('<p>' + action + (intensity?(' — ' + intensity):'') + '</p>');
        win.document.write('<ol>');
        for(let i=1;i<=7;i++) win.document.write('<li>Day ' + i + ': ' + action + '</li>');
        win.document.write('</ol>');
        win.document.write('<script>setTimeout(function(){window.print();},200);</script>');
        win.document.write('</body></html>');
        win.document.close();
      });
    })();
  </script>
</body>
</html>"} 
