<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>Praise — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff;--accent:#6a8a6a;--muted:#6b6b6b}
    body{font-family:Inter,system-ui,Helvetica,Arial;color:#162;line-height:1.5;margin:0;background:linear-gradient(180deg,#fbfbfb,#fff)}
