    nav a{margin:0 12px;text-decoration:none;color:#2a4;font-weight:700}
    .container{max-width:1000px;margin:20px auto;padding:0 20px}
    .cards{display:grid;grid-template-columns:1fr 1fr;gap:18px}
    .card{background:#fff;border-radius:12px;padding:16px;border:1px solid rgba(0,0,0,0.04)}
    blockquote{margin:0;padding:0 0 8px;border-left:4px solid rgba(106,138,106,0.12);padding-left:12px}
