    .btn{background:var(--accent);color:white;padding:10px 12px;border-radius:10px;text-decoration:none;font-weight:700}
    .builder{margin-top:16px;padding:14px;background:linear-gradient(180deg,#fff,#f7f7f5);border-radius:10px;border:1px solid #eee}
